    return `<article class="visual-card" data-card-style="${cardStyle("gallery")}"><div class="visual-image"><img src="${escape(src)}" alt="${uploaded ? `Foto ${escape(title.toLowerCase())} milik ${name}` : `Inspirasi visual ${escape(title.toLowerCase())} · contoh demo`}" loading="lazy"><span>${uploaded ? "FOTO BISNIS" : "VISUAL DEMO"}</span></div><div class="visual-caption"><span>INSPIRASI</span><h3>${escape(item?.title || title)}</h3>${item?.caption ? `<p>${escape(item.caption)}</p>` : ""}</div></article>`;
