    "technology-saas": { label: "TECHNOLOGY · BUILT FOR WHAT'S NEXT", visualTitle: "Teknologi yang menggerakkan ide.", hero: "radial-gradient(ellipse at 75% 15%,#3567a8,#152238 58%,#111827)", navHeight: "72px", radius: "16px", sectionEyebrow: "Platform Capabilities" },
